			attribute_ref_id = etree.SubElement(addfiles, "AttributeRefId", name="BioSample")
			refid = etree.SubElement(attribute_ref_id, "RefId")
			spuid = etree.SubElement(refid, "SPUID", spuid_namespace=config_dict["Spuid_Namespace"])
